#include <iostream>
#include <string>
using namespace std;

class Personagem {
public:
    Personagem(const string& nome, int vida) : nome(nome), vida(vida) {}
    string getNome() const { return nome; }
    int getVida() const { return vida; }
    void receberDano(int dano) {
        vida -= dano;
        if (vida < 0) {
            vida = 0;
        }
    }

protected:
    string nome;
    int vida;
};

class Guerreiro : public Personagem {
public:
    Guerreiro(const string& nome, int vida, int escudo) : Personagem(nome, vida), escudo(escudo) {}

    int getEscudo() const { return escudo; }

    void defender(int dano) {
        int passa = dano - escudo;
        if (passa < 0) {
            passa = 0;
        }
        receberDano(passa);
    }

    string ficha() const {
        return nome + " (Guerreiro): vida " + to_string(vida) + ", escudo " + to_string(escudo);
    }

private:
    int escudo;
};

int main() {
    Guerreiro g("Ana", 30, 4);
    g.defender(10);
    cout << g.ficha() << endl;
    g.defender(3);
    cout << g.ficha() << endl;
    return 0;
}

