#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Inimigo {
public:
    Inimigo(const string& nome) : nome(nome) {}
    string getNome() const { return nome; }
    virtual int ataque() const { return 1; }

protected:
    string nome;
};

class Goblin : public Inimigo {
public:
    Goblin(const string& nome) : Inimigo(nome) {}
    int ataque() const override { return 3; }
};

class Dragao : public Inimigo {
public:
    Dragao(const string& nome, int fogo) : Inimigo(nome), fogo(fogo) {}
    int ataque() const override { return 10 + fogo; }

private:
    int fogo;
};

string anunciar(const Inimigo& inimigo) {
    return inimigo.getNome() + " ataca com força " + to_string(inimigo.ataque());
}

int ataqueTotal(const vector<Inimigo*>& bando) {
    int total = 0;
    for (Inimigo* inimigo : bando) {
        total += inimigo->ataque();
    }
    return total;
}

int main() {
    Goblin g("Gob");
    Dragao d("Ignis", 5);
    vector<Inimigo*> bando = {&g, &d};
    cout << anunciar(g) << endl;
    cout << anunciar(d) << endl;
    cout << "Ataque do bando: " << ataqueTotal(bando) << endl;
    return 0;
}

