#include <iostream>
#include <memory>
#include <string>
using namespace std;

class Criatura {
public:
    Criatura(const string& nome) : nome(nome) {}
    virtual ~Criatura() { cout << nome << " sai da arena." << endl; }
    string getNome() const { return nome; }
    virtual int poder() const = 0;

protected:
    string nome;
};

class Lobo : public Criatura {
public:
    Lobo(const string& nome) : Criatura(nome) {}
    int poder() const override { return 6; }
};

class Golem : public Criatura {
public:
    Golem(const string& nome, int pedras) : Criatura(nome), pedras(pedras) {}
    ~Golem() { cout << nome << " desmorona em " << pedras << " pedras." << endl; }
    int poder() const override { return 4 * pedras; }

private:
    int pedras;
};

int main() {
    unique_ptr<Criatura> lobo = make_unique<Lobo>("Presa");
    Criatura* golem = new Golem("Rocha", 3);
    cout << lobo->getNome() << " tem poder " << lobo->poder() << endl;
    cout << golem->getNome() << " tem poder " << golem->poder() << endl;
    delete golem;
    return 0;
}

