#include <iostream>
using namespace std;

struct Vetor2 {
    int x;
    int y;
};

Vetor2 operator+(const Vetor2& a, const Vetor2& b) {
    return {a.x + b.x, a.y + b.y};
}

bool operator==(const Vetor2& a, const Vetor2& b) {
    return a.x == b.x && a.y == b.y;
}

bool operator!=(const Vetor2& a, const Vetor2& b) {
    return !(a == b);
}

ostream& operator<<(ostream& saida, const Vetor2& v) {
    saida << "(" << v.x << ", " << v.y << ")";
    return saida;
}

int main() {
    Vetor2 posicao = {2, 3};
    Vetor2 velocidade = {1, -1};
    Vetor2 tesouro = {4, 1};
    for (int passo = 1; passo <= 3; passo++) {
        posicao = posicao + velocidade;
        cout << "Passo " << passo << ": " << posicao << endl;
        if (posicao == tesouro) {
            cout << "Tesouro encontrado em " << tesouro << "!" << endl;
        }
    }
    if (posicao != tesouro) {
        cout << "O tesouro ficou para trás." << endl;
    }
    return 0;
}

