#include <iostream>
#include <string>
#include <vector>
using namespace std;

template <typename T>
T limitar(T valor, T minimo, T maximo) {
    if (valor < minimo) {
        return minimo;
    }
    if (valor > maximo) {
        return maximo;
    }
    return valor;
}

template <typename T>
class Pilha {
public:
    void empilhar(const T& item) { itens.push_back(item); }

    bool desempilhar() {
        if (itens.empty()) {
            return false;
        }
        itens.pop_back();
        return true;
    }

    T topo() const { return itens.back(); }
    int tamanho() const { return itens.size(); }
    bool vazia() const { return itens.empty(); }

private:
    vector<T> itens;
};

int main() {
    Pilha<string> acoes;
    acoes.empilhar("parede em (2, 3)");
    acoes.empilhar("porta em (5, 1)");
    cout << "Última ação: " << acoes.topo() << endl;
    acoes.desempilhar();
    cout << "Depois de desfazer: " << acoes.topo() << " (" << acoes.tamanho() << " ação)" << endl;
    cout << limitar(120, 0, 100) << endl;
    cout << limitar(-0.5, 0.0, 1.0) << endl;
    cout << limitar('z', 'a', 'e') << endl;
    return 0;
}

