#include <iostream>
#include <iomanip>
#include <memory>
#include <string>
#include <vector>
using namespace std;

const double PI = 3.141592653589793;

class Forma {
public:
    virtual ~Forma() {}
    virtual string nome() const = 0;
    virtual double area() const = 0;
    virtual double perimetro() const = 0;
};

class Retangulo : public Forma {
public:
    Retangulo(double largura, double altura) : largura(largura), altura(altura) {}
    string nome() const override { return "Retângulo"; }
    double area() const override { return largura * altura; }
    double perimetro() const override { return 2 * (largura + altura); }

protected:
    double largura;
    double altura;
};

class Quadrado : public Retangulo {
public:
    Quadrado(double lado) : Retangulo(lado, lado) {}
    string nome() const override { return "Quadrado"; }
};

class Circulo : public Forma {
public:
    Circulo(double raio) : raio(raio) {}
    string nome() const override { return "Círculo"; }
    double area() const override { return PI * raio * raio; }
    double perimetro() const override { return 2 * PI * raio; }

private:
    double raio;
};

ostream& operator<<(ostream& saida, const Forma& forma) {
    saida << fixed << setprecision(2);
    saida << forma.nome() << ": área " << forma.area() << ", perímetro " << forma.perimetro();
    return saida;
}

template <typename Colecao>
double areaTotal(const Colecao& formas) {
    double total = 0;
    for (const auto& forma : formas) {
        total += forma->area();
    }
    return total;
}

void relatorio(const vector<unique_ptr<Forma>>& formas) {
    int numero = 1;
    for (const auto& forma : formas) {
        cout << numero << ". " << *forma << endl;
        numero++;
    }
    cout << "Área total: " << fixed << setprecision(2) << areaTotal(formas) << endl;
}

int main() {
    vector<unique_ptr<Forma>> formas;
    formas.push_back(make_unique<Retangulo>(3, 4));
    formas.push_back(make_unique<Quadrado>(2));
    formas.push_back(make_unique<Circulo>(1));
    relatorio(formas);
    return 0;
}
